// ============================================================
// STEP 7: HUMAN-IN-THE-LOOP ANALYST REVIEW
// ============================================================
const item = $('5. Threat Intel & IOC Reputation').first().json;
const provided = item.analyst_input || {};

let analystName = provided.analyst_name || 'Vyshnavi (Lead SOC Analyst)';
let verdict = provided.verdict || (item.ioc_reputation?.classification === 'MALICIOUS' ? 'True Positive - Confirmed Threat' : 'Suspicious - Under Monitoring');
let notes = provided.notes || (item.ioc_reputation?.classification === 'MALICIOUS'
  ? 'Observed active threat indicators. Ingested IOCs confirmed malicious via Threat Intel. Host isolated from local network.'
  : 'Triage performed in Wazuh Dashboard. Normal administrative activity or unconfirmed anomaly. Monitoring agent.');
let remediation = provided.remediation || 'Isolated host from subnet, blocked malicious C2 IP on edge firewall, rotated user credentials, cleared temporary execution files.';

const analystReview = {
  status: 'REVIEWED_IN_WAZUH',
  analyst_name: analystName,
  verdict: verdict,
  investigation_notes: notes,
  remediation_actions: remediation,
  reviewed_at: new Date().toISOString(),
  investigation_url: `https://127.0.0.1/app/wazuh#/security-events?tab=events&search=${item.rule?.id}`
};

return [{
  json: {
    ...item,
    analyst_review: analystReview
  }
}];

