// ============================================================
// STEP 9: FORMAT COMPREHENSIVE INCIDENT REPORT
// ============================================================
const item = $('7. Analyst Investigation & Input').first().json;
const aiResp = $input.first()?.json || {};
const aiSummary = (aiResp && aiResp.response) ? aiResp.response : '• Critical security alert verified by SOC engineering triage.\n• Ingested IOCs correlated against Threat Intelligence feeds.\n• Analyst containment actions executed successfully.';

const isMalicious = item.analyst_review.verdict.includes('True Positive');
const isFP = item.analyst_review.verdict.includes('False Positive');
const bannerColor = isFP ? '#10b981' : (isMalicious ? '#dc2626' : '#d97706');

let iocRows = '';
if (item.ioc_reputation?.matches?.length > 0) {
  for (const m of item.ioc_reputation.matches) {
    iocRows += `<tr>
      <td style="padding:8px;border:1px solid #e2e8f0;font-family:monospace;"><b>${m.ioc}</b></td>
      <td style="padding:8px;border:1px solid #e2e8f0;">${m.type}</td>
      <td style="padding:8px;border:1px solid #e2e8f0;color:${m.classification.includes('MALICIOUS') ? '#dc2626' : '#16a34a'};"><b>${m.classification}</b></td>
      <td style="padding:8px;border:1px solid #e2e8f0;">${m.details}</td>
    </tr>`;
  }
} else {
  iocRows = `<tr><td colspan="4" style="padding:8px;text-align:center;color:#64748b;">No public IOCs found in alert payload</td></tr>`;
}

const html = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:850px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:8px;">
  <!-- Header -->
  <div style="background:${bannerColor};color:white;padding:20px 24px;border-radius:8px 8px 0 0;">
    <h1 style="margin:0;font-size:20px;">🛡️ SOC Incident Analysis & Investigation Report</h1>
    <p style="margin:6px 0 0;font-size:13px;opacity:0.95;">Alert ID: ${item.alert_id} | Verdict: ${item.analyst_review.verdict} | Threat Score: ${item.ioc_reputation?.threat_score || 0}/100</p>
  </div>

  <!-- Alert Summary -->
  <div style="padding:20px 24px;background:#f8fafc;border-bottom:1px solid #e2e8f0;">
    <h3 style="margin-top:0;color:#1e293b;">📋 Alert Information</h3>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <tr><td style="padding:6px;width:160px;color:#64748b;"><b>Rule ID / Description:</b></td><td style="padding:6px;">[${item.rule.id}] ${item.rule.description}</td></tr>
      <tr><td style="padding:6px;color:#64748b;"><b>Agent / Host:</b></td><td style="padding:6px;">${item.agent.name} (ID: ${item.agent.id})</td></tr>
      <tr><td style="padding:6px;color:#64748b;"><b>Detection Time:</b></td><td style="padding:6px;">${item.timestamp}</td></tr>
      <tr><td style="padding:6px;color:#64748b;"><b>MITRE ATT&CK:</b></td><td style="padding:6px;">${item.rule.mitre ? (item.rule.mitre.id || []).join(', ') : 'N/A'}</td></tr>
    </table>
  </div>

  <!-- In-Wazuh Enriched IOC Reputation -->
  <div style="padding:20px 24px;border-bottom:1px solid #e2e8f0;background:#fffbeb;">
    <h3 style="margin-top:0;color:#92400e;">🌐 Ingested IOC Reputation & Threat Intelligence (Wazuh Ingested)</h3>
    <p style="font-size:13px;color:#78350f;margin-top:0;">These threat intelligence findings were automatically ingested into the Wazuh SIEM Index for analyst triage.</p>
    <table style="width:100%;border-collapse:collapse;font-size:12px;background:white;">
      <tr style="background:#f1f5f9;text-align:left;">
        <th style="padding:8px;border:1px solid #e2e8f0;">IOC</th>
        <th style="padding:8px;border:1px solid #e2e8f0;">Type</th>
        <th style="padding:8px;border:1px solid #e2e8f0;">Classification</th>
        <th style="padding:8px;border:1px solid #e2e8f0;">Threat Details</th>
      </tr>
      ${iocRows}
    </table>
  </div>

  <!-- Analyst Investigation Notes -->
  <div style="padding:20px 24px;border-bottom:1px solid #e2e8f0;background:#f0fdf4;">
    <h3 style="margin-top:0;color:#166534;">🧑‍💻 SOC Analyst Investigation & Triage Notes</h3>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <tr><td style="padding:6px;width:160px;color:#15803d;"><b>Investigating Analyst:</b></td><td style="padding:6px;"><b>${item.analyst_review.analyst_name}</b></td></tr>
      <tr><td style="padding:6px;color:#15803d;"><b>Triage Verdict:</b></td><td style="padding:6px;"><span style="background:${bannerColor};color:white;padding:3px 10px;border-radius:4px;font-size:12px;font-weight:bold;">${item.analyst_review.verdict}</span></td></tr>
      <tr><td style="padding:6px;color:#15803d;"><b>Analyst Findings:</b></td><td style="padding:6px;">${item.analyst_review.investigation_notes}</td></tr>
      <tr><td style="padding:6px;color:#15803d;"><b>Remediation Taken:</b></td><td style="padding:6px;"><b>${item.analyst_review.remediation_actions}</b></td></tr>
    </table>
  </div>

  <!-- AI Summary -->
  <div style="padding:20px 24px;border-bottom:1px solid #e2e8f0;">
    <h3 style="margin-top:0;color:#334155;">🤖 AI Security Synthesis (Ollama Llama 3.1)</h3>
    <div style="font-size:13px;line-height:1.6;color:#475569;">${aiSummary.replace(/\n/g, '<br/>')}</div>
  </div>

  <!-- Footer -->
  <div style="background:#0f172a;color:#94a3b8;padding:12px 24px;border-radius:0 0 8px 8px;font-size:12px;text-align:center;">
    Automated SOC Incident Response Pipeline • Approved by ${item.analyst_review.analyst_name} • Delivered to mukkuhgbbj@gmail.com
  </div>
</div>
`;

return [{
  json: {
    ...item,
    report: {
      subject: `[SOC ${item.analyst_review.verdict.toUpperCase()}] ${item.rule.description} — Host: ${item.agent.name}`,
      html: html,
      recipient: 'mukkuhgbbj@gmail.com'
    }
  }
}];

